set-variable.value:
@{
        var authorization = context.Request.Headers.GetValueOrDefault("Authorization", "");
        return authorization.StartsWith("Be" + "arer ", StringComparison.OrdinalIgnoreCase)
            ? authorization.Substring(7)
            : string.Empty;
    }

when.condition:
@{
            var response = context.Variables["keycloak-introspection-response"] as IResponse;
            if (response == null || response.StatusCode != 200) {
                return true;
            }
            try {
                var payload = response.Body.As<Newtonsoft.Json.Linq.JObject>();
                var active = payload["active"]?.Value<bool>() == true;
                var authorizedParty = payload["azp"]?.ToString() == "{keycloak-client-id}";
                var scopes = (payload["scope"]?.ToString() ?? string.Empty)
                    .Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                var scopeAllowed = scopes.Contains("{keycloak-scope}");
                var audienceClaim = payload["aud"];
                var audienceAllowed = audienceClaim is Newtonsoft.Json.Linq.JArray
                    ? ((Newtonsoft.Json.Linq.JArray)audienceClaim).Any(v => v.ToString() == "{keycloak-audience}")
                    : audienceClaim?.ToString() == "{keycloak-audience}";
                return !(active && authorizedParty && scopeAllowed && audienceAllowed);
            } catch {
                return true;
            }
        }
